export function LanguageProvider({children}){
  const [language,setLanguageState]=useState(()=>localStorage.getItem('bawaslu-language')||'en');
  const setLanguage=next=>setLanguageState(next==='id'?'id':'en');
  useEffect(()=>{
    localStorage.setItem('bawaslu-language',language);
    document.documentElement.lang=language==='id'?'id':'en';
  },[language]);
  const api=useMemo(()=>({
    language,
    setLanguage,
    t:key=>translations[language]?.[key]??extendedTranslations[language]?.[key]??translations.en[key]??extendedTranslations.en[key]??key,
    label:value=>valueLabels[language]?.[value]??value
  }),[language]);
  return <LanguageContext.Provider value={api}>{children}</LanguageContext.Provider>;
}

export function useLanguage(){
  const ctx=useContext(LanguageContext);
  if(!ctx)throw new Error('useLanguage must be used inside LanguageProvider');
  return ctx;
}
